@namespace sv_e53a9157473c41e880afe15e8ca3a7f4.Components.Pages.Apply

<section class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label for="cover-letter">Write your cover letter</label>
        <textarea id="cover-letter" rows="12" maxlength="@MaxLength"
                  @bind="CoverLetterText" @bind:event="oninput"></textarea>
        <div class="char-count @(CoverLetterText.Length >= MaxLength ? "at-limit" : "")">
            @CoverLetterText.Length / @MaxLength characters
        </div>
    </div>

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    private const int MaxLength = 2000;

    [Parameter, EditorRequired] public string CoverLetterText { get; set; } = string.Empty;
    [Parameter, EditorRequired] public EventCallback<string> CoverLetterTextChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private async Task HandleNext()
    {
        await CoverLetterTextChanged.InvokeAsync(CoverLetterText);
        await OnNext.InvokeAsync();
    }
}

@namespace sv_e53a9157473c41e880afe15e8ca3a7f4.Components.Pages.Apply

<section class="step-content review-step">
    <h2>Review &amp; Submit</h2>

    @if (IsSubmitted)
    {
        <div class="confirmation" role="alert">
            <h3>&#10003; Application Submitted!</h3>
            <p>Your application has been received. Your application ID is <strong>@ApplicationId</strong>.</p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="validation-error" role="alert">@ErrorMessage</div>
        }

        <div class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Full Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-item">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <span class="date-range">
                        @entry.StartDate.ToString("MMM yyyy") –
                        @(entry.IsCurrentPosition ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var reference in References)
            {
                <div class="review-item">
                    <strong>@reference.Name</strong> (@reference.Relationship)
                    <br />@reference.Email @(!string.IsNullOrWhiteSpace(reference.Phone) ? $"| {reference.Phone}" : "")
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </div>

        <div class="step-actions">
            <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
            <button type="button" class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</section>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = [];
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = [];
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = string.Empty;
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnEditSection { get; set; }
    [Parameter, EditorRequired] public Func<Task<int>> OnSubmit { get; set; } = default!;

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int ApplicationId;
    private string? ErrorMessage;

    private async Task HandleSubmit()
    {
        IsSubmitting = true;
        ErrorMessage = null;
        try
        {
            ApplicationId = await OnSubmit();
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

