@namespace sv_e53a9157473c41e880afe15e8ca3a7f4.Components.Pages.Apply

namespace sv_e53a9157473c41e880afe15e8ca3a7f4.Components.Pages.Apply;

public record PersonalInfoModel
{
    public string FullName { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string Phone { get; set; } = string.Empty;
    public string Address { get; set; } = string.Empty;
}

public record WorkEntryModel
{
    public string Company { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public DateTime StartDate { get; set; } = DateTime.Today;
    public DateTime? EndDate { get; set; }
    public string Description { get; set; } = string.Empty;
    public bool IsCurrentPosition { get; set; }
}

public record ReferenceModel
{
    public string Name { get; set; } = string.Empty;
    public string Relationship { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string Phone { get; set; } = string.Empty;
}

@page "/apply"
@using sv_e53a9157473c41e880afe15e8ca3a7f4.Models
@namespace sv_e53a9157473c41e880afe15e8ca3a7f4.Components.Pages.Apply
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep"
                   StepNames="@stepNames"
                   CompletedSteps="@completedSteps"
                   OnNavigate="NavigateToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="@personalInfo"
                              ModelChanged="model => personalInfo = model"
                              OnNext="GoToNextStep"
                              ValidateEmail="ValidateEmailAsync" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             EntriesChanged="entries => workEntries = entries"
                             OnNext="GoToNextStep"
                             OnBack="GoToPreviousStep" />
            break;
        case 2:
            <ReferencesStep Entries="@references"
                            EntriesChanged="entries => references = entries"
                            OnNext="GoToNextStep"
                            OnBack="GoToPreviousStep" />
            break;
        case 3:
            <CoverLetterStep CoverLetterText="@coverLetter"
                             CoverLetterTextChanged="text => coverLetter = text"
                             OnNext="GoToNextStep"
                             OnBack="GoToPreviousStep" />
            break;
        case 4:
            <ReviewStep Personal="@personalInfo"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnBack="GoToPreviousStep"
                        OnEditSection="NavigateToStep"
                        OnSubmit="SubmitApplicationAsync" />
            break;
    }
</div>

@code {
    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private int currentStep;
    private readonly HashSet<int> completedSteps = new();

    private static readonly IReadOnlyList<string> stepNames = new[]
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = [new()];
    private List<ReferenceModel> references = [new(), new()];
    private string coverLetter = string.Empty;

    private void GoToNextStep()
    {
        completedSteps.Add(currentStep);
        currentStep++;
    }

    private void GoToPreviousStep()
    {
        currentStep--;
    }

    private void NavigateToStep(int step)
    {
        currentStep = step;
    }

    private async Task<bool> ValidateEmailAsync(string email)
    {
        return await ApplicationService.ValidateEmailAsync(email);
    }

    private async Task<int> SubmitApplicationAsync()
    {
        var application = new JobApplication(
            Personal: new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
            Work: new WorkHistory(workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate, e.IsCurrentPosition ? null : e.EndDate, e.Description
            )).ToList()),
            References: references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            CoverLetter: coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

