toolArgs.file_text:
.application-form {
    max-width: 800px;
    margin: 2rem auto;
    padding: 1.5rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 2rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    gap: 0;
}

.step-indicator .step {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem;
    min-width: 80px;
    font-size: 0.8rem;
    transition: opacity 0.2s;
}

.step-indicator .step.future {
    opacity: 0.4;
    cursor: not-allowed;
}

.step-indicator .step.current .step-number {
    background: #2563eb;
    color: white;
    font-weight: bold;
}

.step-indicator .step.completed .step-number {
    background: #16a34a;
    color: white;
}

.step-number {
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #e5e7eb;
    color: #6b7280;
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.step-label {
    white-space: nowrap;
}

.step-connector {
    width: 2rem;
    height: 2px;
    background: #e5e7eb;
    margin-bottom: 1.2rem;
}

.step-connector.completed {
    background: #16a34a;
}

/* Step content */
.step-content {
    background: #f9fafb;
    border: 1px solid #e5e7eb;
    border-radius: 0.5rem;
    padding: 1.5rem;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1rem;
    border-bottom: 1px solid #e5e7eb;
    padding-bottom: 0.5rem;
}

/* Form elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #d1d5db;
    border-radius: 0.25rem;
    font-size: 1rem;
}

.form-group textarea {
    resize: vertical;
}

.form-row {
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
}

.form-row .form-group {
    flex: 1;
    min-width: 150px;
}

.form-group-checkbox {
    display: flex;
    align-items: flex-end;
    padding-bottom: 0.5rem;
}

.form-group-checkbox label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal;
}

/* Buttons */
.step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #e5e7eb;
}

.btn-primary {
    background: #2563eb;
    color: white;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 0.25rem;
    font-size: 1rem;
    cursor: pointer;
    margin-left: auto;
}

.btn-primary:hover:not(:disabled) {
    background: #1d4ed8;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-outline {
    background: white;
    color: #374151;
    border: 1px solid #d1d5db;
    padding: 0.6rem 1.5rem;
    border-radius: 0.25rem;
    font-size: 1rem;
    cursor: pointer;
}

.btn-outline:hover {
    background: #f3f4f6;
}

.btn-secondary {
    background: #f3f4f6;
    color: #374151;
    border: 1px solid #d1d5db;
    padding: 0.5rem 1rem;
    border-radius: 0.25rem;
    font-size: 0.9rem;
    cursor: pointer;
    margin-top: 0.5rem;
}

.btn-secondary:hover {
    background: #e5e7eb;
}

.btn-remove {
    background: #fee2e2;
    color: #dc2626;
    border: 1px solid #fca5a5;
    padding: 0.4rem 0.8rem;
    border-radius: 0.25rem;
    font-size: 0.85rem;
    cursor: pointer;
    margin-top: 0.5rem;
}

.btn-remove:hover {
    background: #fecaca;
}

.btn-link {
    background: none;
    border: none;
    color: #2563eb;
    cursor: pointer;
    text-decoration: underline;
    font-size: 0.9rem;
    padding: 0;
}

.btn-link:hover {
    color: #1d4ed8;
}

.btn-submit {
    font-size: 1.1rem;
    padding: 0.75rem 2rem;
}

/* Validation */
.validation-error {
    background: #fee2e2;
    border: 1px solid #fca5a5;
    color: #dc2626;
    padding: 0.75rem;
    border-radius: 0.25rem;
    margin-bottom: 1rem;
}

/* Fieldsets */
fieldset {
    border: 1px solid #e5e7eb;
    border-radius: 0.25rem;
    padding: 1rem;
    margin-bottom: 1rem;
}

fieldset legend {
    font-weight: 600;
    padding: 0 0.5rem;
}

/* Character count */
.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #6b7280;
    margin-top: 0.25rem;
}

.char-count.at-limit {
    color: #dc2626;
    font-weight: 600;
}

/* Hints */
.hint {
    color: #6b7280;
    font-size: 0.9rem;
    margin-bottom: 1rem;
}

/* Review step */
.review-section {
    margin-bottom: 1.5rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid #e5e7eb;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.review-header h3 {
    margin: 0 0 0.5rem 0;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #6b7280;
}

.review-section dd {
    margin: 0;
}

.review-item {
    padding: 0.5rem 0;
}

.review-item + .review-item {
    border-top: 1px solid #f3f4f6;
}

.date-range {
    font-size: 0.9rem;
    color: #6b7280;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: white;
    padding: 1rem;
    border: 1px solid #e5e7eb;
    border-radius: 0.25rem;
    max-height: 200px;
    overflow-y: auto;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 2rem;
    background: #f0fdf4;
    border: 1px solid #86efac;
